// usage: node snap.mjs <baseUrl> <outDir>
import { writeFileSync } from 'node:fs'
import { join } from 'node:path'
const [base, out] = process.argv.slice(2)
const enc = v => encodeURIComponent(JSON.stringify(v))
const cases = {
  index: { path: '/' },
  'product-notebook': { path: '/products/notebook' },
  'cart-empty': { path: '/cart' },
  'checkout-empty': { path: '/checkout', redirect: 'manual' },
  'cart-full': { path: '/cart', cookie: `cart=${enc([{ slug: 'notebook', qty: 2 }, { slug: 'pencil', qty: 1 }])}; discount-code=SAVE10` },
  'checkout-full': { path: '/checkout', cookie: `cart=${enc([{ slug: 'notebook', qty: 2 }])}; discount-code=HALF`, redirect: 'manual' },
  'product-add-cookie': { path: '/products/pencil' },
}
for (const [name, c] of Object.entries(cases)) {
  const res = await fetch(base + c.path, { headers: c.cookie ? { cookie: c.cookie } : {}, redirect: c.redirect ?? 'follow' })
  const body = await res.text()
  writeFileSync(join(out, `${name}.html`), `${res.status} ${res.headers.get('location') ?? ''}\n${body}`)
  console.log(name, res.status, res.headers.get('location') ?? '', body.length)
}
const q = await fetch(base + '/api/cart/quote', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ lines: [{ slug: 'notebook', qty: 2 }], code: 'SAVE10' }) })
writeFileSync(join(out, 'quote.json'), await q.text())
console.log('quote', q.status)
EOF
